import{_ as t,a,o as r,a6 as o}from"./chunks/framework.CJDy2q7X.js";const u=JSON.parse('{"title":"Customer","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/graphql-api/shop/customer/index.md","filePath":"api/graphql-api/shop/customer/index.md","lastUpdated":1787290888000}'),d={name:"api/graphql-api/shop/customer/index.md"};function s(i,e,h,n,c,l){return r(),a("div",null,e[0]||(e[0]=[o('<h1 id="customer" tabindex="-1">Customer <a class="header-anchor" href="#customer" aria-label="Permalink to &quot;Customer&quot;">​</a></h1><p>The Customer menu is the customer&#39;s account area — registering and signing in, managing the profile and address book, viewing past orders, invoices, shipments, and downloadable products, and managing their own reviews. It backs every &quot;My Account&quot; screen on the storefront.</p><h2 id="authentication-session" tabindex="-1">Authentication &amp; session <a class="header-anchor" href="#authentication-session" aria-label="Permalink to &quot;Authentication &amp; session&quot;">​</a></h2><p>A customer registers, then logs in to receive a <strong>Bearer token</strong>. That token is sent on every account operation (and is the same token used by Cart, Checkout, Wishlist, and Compare). The token can be verified, and logging out invalidates it. Forgot Password starts the password-reset flow by email.</p><h2 id="what-you-can-do" tabindex="-1">What you can do <a class="header-anchor" href="#what-you-can-do" aria-label="Permalink to &quot;What you can do&quot;">​</a></h2><ul><li><strong>Profile</strong> — read, update, or delete the signed-in customer&#39;s account.</li><li><strong>Orders</strong> — list the customer&#39;s orders, view one order in detail, view its shipments, and cancel or reorder an order.</li><li><strong>Invoices</strong> — list invoices and view one. The PDF itself is fetched over REST from the invoice&#39;s <code>downloadUrl</code>.</li><li><strong>Downloadable products</strong> — list the customer&#39;s purchased downloads and read how many uses remain. The file itself is fetched over REST.</li><li><strong>Addresses</strong> — list, create, update, and delete saved addresses (the address book).</li><li><strong>Reviews</strong> — read the reviews the customer has written. Submitting one is on <a href="/api/graphql-api/shop/mutations/create-product-review.html">Create Product Review</a>.</li></ul><h2 id="operations" tabindex="-1">Operations <a class="header-anchor" href="#operations" aria-label="Permalink to &quot;Operations&quot;">​</a></h2><h3 id="profile-and-session" tabindex="-1">Profile and session <a class="header-anchor" href="#profile-and-session" aria-label="Permalink to &quot;Profile and session&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Operation</th><th>GraphQL field</th><th>Description</th></tr></thead><tbody><tr><td>Register</td><td><a href="/api/graphql-api/shop/mutations/customer-registration.html"><code>createCustomer</code></a></td><td>Create a customer account.</td></tr><tr><td>Log in</td><td><a href="/api/graphql-api/shop/mutations/customer-login.html"><code>createCustomerLogin</code></a></td><td>Exchange credentials for a Bearer token.</td></tr><tr><td>Verify a token</td><td><a href="/api/graphql-api/shop/mutations/customer-verify-token.html"><code>createVerifyToken</code></a></td><td>Check whether a stored token is still valid.</td></tr><tr><td>Log out</td><td><a href="/api/graphql-api/shop/mutations/customer-logout.html"><code>createLogout</code></a></td><td>Invalidate the current token.</td></tr><tr><td>Start a password reset</td><td><a href="/api/graphql-api/shop/mutations/forgot-password.html"><code>createForgotPassword</code></a></td><td>Email the customer a reset link.</td></tr><tr><td>Read the profile</td><td><a href="/api/graphql-api/shop/queries/get-customer-profile.html"><code>readCustomerProfile</code></a></td><td>The signed-in customer&#39;s account details.</td></tr><tr><td>Update the profile</td><td><a href="/api/graphql-api/shop/mutations/update-customer-profile.html"><code>createCustomerProfileUpdate</code></a></td><td>Change name, email, phone, or password.</td></tr><tr><td>Delete the account</td><td><a href="/api/graphql-api/shop/mutations/delete-customer-profile.html"><code>createCustomerProfileDelete</code></a></td><td>Close the customer&#39;s own account.</td></tr></tbody></table><h3 id="orders" tabindex="-1">Orders <a class="header-anchor" href="#orders" aria-label="Permalink to &quot;Orders&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Operation</th><th>GraphQL field</th><th>Description</th></tr></thead><tbody><tr><td>List orders</td><td><a href="/api/graphql-api/shop/queries/get-customer-orders.html"><code>customerOrders</code></a></td><td>The customer&#39;s own orders, paginated.</td></tr><tr><td>View one order</td><td><a href="/api/graphql-api/shop/queries/get-customer-order.html"><code>customerOrder</code></a></td><td>Full order detail with items, addresses, and payment.</td></tr><tr><td>List shipments</td><td><a href="/api/graphql-api/shop/queries/get-customer-order-shipments.html"><code>customerOrderShipments</code></a></td><td>Shipments across the customer&#39;s orders.</td></tr><tr><td>View one shipment</td><td><a href="/api/graphql-api/shop/queries/get-customer-order-shipment.html"><code>customerOrderShipment</code></a></td><td>A single shipment with its items.</td></tr><tr><td>Cancel an order</td><td><a href="/api/graphql-api/shop/mutations/cancel-customer-order.html"><code>createCancelOrder</code></a></td><td>Cancel an order that is still cancellable.</td></tr><tr><td>Reorder</td><td><a href="/api/graphql-api/shop/mutations/reorder-customer-order.html"><code>createReorderOrder</code></a></td><td>Rebuild a cart from a past order.</td></tr></tbody></table><h3 id="invoices" tabindex="-1">Invoices <a class="header-anchor" href="#invoices" aria-label="Permalink to &quot;Invoices&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Operation</th><th>GraphQL field</th><th>Description</th></tr></thead><tbody><tr><td>List invoices</td><td><a href="/api/graphql-api/shop/queries/get-customer-invoices.html"><code>customerInvoices</code></a></td><td>Invoices raised against the customer&#39;s orders.</td></tr><tr><td>View one invoice</td><td><a href="/api/graphql-api/shop/queries/get-customer-invoice.html"><code>customerInvoice</code></a></td><td>A single invoice with its totals and items.</td></tr><tr><td>Download the PDF</td><td><a href="/api/graphql-api/shop/queries/download-invoice.html"><code>customerInvoice</code></a></td><td>Read <code>downloadUrl</code> from the invoice, then fetch the PDF over REST — GraphQL cannot return a binary.</td></tr></tbody></table><h3 id="downloadable-products" tabindex="-1">Downloadable products <a class="header-anchor" href="#downloadable-products" aria-label="Permalink to &quot;Downloadable products&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Operation</th><th>GraphQL field</th><th>Description</th></tr></thead><tbody><tr><td>List purchases</td><td><a href="/api/graphql-api/shop/queries/get-customer-downloadable-products.html"><code>customerDownloadableProducts</code></a></td><td>Downloadable products the customer has bought, with remaining downloads.</td></tr><tr><td>View one purchase</td><td><a href="/api/graphql-api/shop/queries/get-customer-downloadable-product.html"><code>customerDownloadableProduct</code></a></td><td>A single purchased download.</td></tr><tr><td>Download the file</td><td><a href="/api/graphql-api/shop/queries/download-downloadable-product.html">REST only</a></td><td>The file is served over REST; use the <code>downloadUrl</code> from the queries above.</td></tr></tbody></table><h3 id="addresses" tabindex="-1">Addresses <a class="header-anchor" href="#addresses" aria-label="Permalink to &quot;Addresses&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Operation</th><th>GraphQL field</th><th>Description</th></tr></thead><tbody><tr><td>List addresses</td><td><a href="/api/graphql-api/shop/queries/get-customer-addresses.html"><code>getCustomerAddresses</code></a></td><td>The customer&#39;s saved address book.</td></tr><tr><td>Create an address</td><td><a href="/api/graphql-api/shop/mutations/create-customer-address.html"><code>createAddUpdateCustomerAddress</code></a></td><td>Add a new address.</td></tr><tr><td>Update an address</td><td><a href="/api/graphql-api/shop/mutations/update-customer-address.html"><code>createAddUpdateCustomerAddress</code></a></td><td>The same mutation — supplying an existing address ID updates it instead of adding one.</td></tr><tr><td>Delete an address</td><td><a href="/api/graphql-api/shop/mutations/delete-customer-address.html"><code>createDeleteCustomerAddress</code></a></td><td>Remove an address from the book.</td></tr></tbody></table><h3 id="reviews" tabindex="-1">Reviews <a class="header-anchor" href="#reviews" aria-label="Permalink to &quot;Reviews&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Operation</th><th>GraphQL field</th><th>Description</th></tr></thead><tbody><tr><td>List own reviews</td><td><a href="/api/graphql-api/shop/queries/get-customer-reviews.html"><code>customerReviews</code></a></td><td>Reviews the customer has written.</td></tr><tr><td>View one review</td><td><a href="/api/graphql-api/shop/queries/get-customer-review.html"><code>customerReview</code></a></td><td>A single review the customer owns.</td></tr></tbody></table><p>Registration, Login, and Forgot Password are public (storefront key only); every other operation requires a customer Bearer token — see <a href="/api/graphql-api/authentication.html">Authentication</a>.</p>',20)]))}const m=t(d,[["render",s]]);export{u as __pageData,m as default};
